enum Check { Passed, Unknown, Failed(String) }

// `reply` is the raw text of a second model call that lists passages
// of a question's reasons that discuss answers which are not offered.
fn judge(reply: &str) -> Check {
    match parse::<Unlisted>(reply) {
        Err(_) => Check::Failed("check reply unreadable".into()),
        Ok(out) if out.unlisted.is_empty() => Check::Passed,
        Ok(out) => Check::Failed(format!("unlisted answers: {:?}", out.unlisted)),
    }
}

